'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var Float64Array = require( '@stdlib/array/float64' );
var dcurange = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dcurange, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 7', function test( t ) {
	t.strictEqual( dcurange.length, 7, 'has expected arity' );
	t.end();
});

tape( 'the function computes the cumulative range of a strided array', function test( t ) {
	var expected;
	var x;
	var y;

	x = new Float64Array( [ 1.0, -2.0, 2.0 ] );
	y = new Float64Array( 3 );
	expected = new Float64Array( [ 0.0, 3.0, 4.0 ] );

	dcurange( x.length, x, 1, 0, y, 1, 0 );
	t.deepEqual( y, expected, 'returns expected values' );

	x = new Float64Array( [ -2.0, 1.0, 1.0, -5.0, 2.0, -1.0 ] );
	y = new Float64Array( 3 );
	expected = new Float64Array( [ 0.0, 3.0, 4.0 ] );

	dcurange( 3, x, 2, 0, y, 1, 0 );
	t.deepEqual( y, expected, 'returns expected values' );

	t.end();
});

tape( 'if provided N <= 0, the function returns y unchanged', function test( t ) {
	var expected;
	var x;
	var y;

	x = new Float64Array( [ 1.0, -2.0, 3.0 ] );
	y = new Float64Array( [ 9.0, 9.0, 9.0 ] );
	expected = new Float64Array( [ 9.0, 9.0, 9.0 ] );

	dcurange( 0, x, 1, 0, y, 1, 0 );
	t.deepEqual( y, expected, 'returns expected values' );

	dcurange( -1, x, 1, 0, y, 1, 0 );
	t.deepEqual( y, expected, 'returns expected values' );

	t.end();
});

tape( 'the function supports a stride parameter', function test( t ) {
	var expected;
	var x;
	var y;

	x = new Float64Array([
		1.0,
		2.0,
		2.0,
		-7.0,
		-2.0,
		3.0,
		4.0,
		2.0
	]);
	y = new Float64Array( 4 );
	expected = new Float64Array( [ 0.0, 1.0, 4.0, 6.0 ] );
	dcurange( 4, x, 2, 0, y, 1, 0 );

	t.deepEqual( y, expected, 'returns expected values' );
	t.end();
});

tape( 'the function supports a negative stride parameter', function test( t ) {
	var expected;
	var x;
	var y;

	x = new Float64Array([ 1.0, 2.0, 2.0, -7.0, -2.0, 3.0, 4.0, 2.0 ]);
	y = new Float64Array( 4 );
	expected = new Float64Array( [ 0.0, 6.0, 6.0, 6.0 ] );

	dcurange( 4, x, -2, 6, y, 1, 0 );
	t.deepEqual( y, expected, 'returns expected values' );

	t.end();
});

tape( 'the function supports an offset parameter', function test( t ) {
	var expected;
	var x;
	var y;

	x = new Float64Array([ 2.0, 1.0, 2.0, -2.0, -2.0, 2.0, 3.0, 4.0 ]);
	y = new Float64Array( 4 );
	expected = new Float64Array( [ 0.0, 3.0, 4.0, 6.0 ] );
	dcurange( 4, x, 2, 1, y, 1, 0 );

	t.deepEqual( y, expected, 'returns expected values' );
	t.end();
});

tape( 'if the input contains NaN, all subsequent values are NaN', function test( t ) {
	var x;
	var y;

	x = new Float64Array( [ 1.0, NaN, 2.0 ] );
	y = new Float64Array( 3 );

	dcurange( 3, x, 1, 0, y, 1, 0 );

	t.strictEqual( y[0], 0.0, 'returns expected values' );
	t.strictEqual( isnan( y[1] ), true, 'returns expected values' );
	t.strictEqual( isnan( y[2] ), true, 'returns expected values' );

	t.end();
});
